const bytecode = ""


const provider = new ethers.JsonRpcProvider(process.env.TESTNET_RPC)

export async function deployConcert(privateKey, timeStartSale, timeEndSale, fee, tickets){
    const wallet = new ethers.Wallet(privateKey, provider);
    const factory = new ethers.ContractFactory(abi, bytecode, wallet);
    try {
        let prices = []
        let supplies = []
        tickets.forEach((ticket) =>  {
            prices.push(ticket.price)
            supplies.push(ticket.supply)
        })
        const contract = await factory.deploy(process.env.CONTRACT_ADDRESS, timeStartSale, timeEndSale, fee, prices, supplies);
        console.log("Deploying Contract...");
        await contract.waitForDeployment()
        console.log("Contract Address:", contract.target);
        
        return {result: contract.target};
    } catch (error) {
    return {error}
    }
}
export async function buyTicketContract(privateKey, concertAddress, cart, totalPayment) {
    try{
    const wallet = new ethers.Wallet(privateKey, provider);
    const contract = new ethers.Contract(concertAddress, abi, wallet)
    const tx = await contract.buyTicket(cart, {value: totalPayment})
    return tx
    }
    catch(error){
        return error
    }
}
export async function getEmit(receipt, contractAddress) {
    const iface = new ethers.Interface(abi);
    const ticketIds = []
    for (const Log of receipt.logs) {
        if (Log.args) {
            ticketIds.push(parseInt(Log.args[0]))
        }
    }
    return ticketIds
}